# median :: [1, 2, 3, 4, 5]
def median(xs):
    if not xs:
        return None
    s = sorted(xs)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    return (s[n // 2 - 1] + s[n // 2]) / 2

if __name__ == '__main__':
    print(median([1, 2, 3, 4, 5]))

